powerpagecomponent.content:
{
  "source": "{%- assign ctaText = ctaLabel | default: 'View Program' -%}
{%- assign targetAttributes = targetAttrs | default: targetAttr | default: '' -%}

{%- comment -%}
Featured card that matches existing CSS selectors:
- .hit-card__inner--featured (aspect ratio + background image)
- .hit-card__overlay
- .hit-card__body--featured
- .hit-card__title--featured
- .hit-card__summary--featured
- .hit-card__stretchedLink (z-index safety rules)
{%- endcomment -%}

{%- assign bgStyle = '' -%}
{%- if imageUrl and imageUrl != '' -%}
  {%- assign bgStyle = 'background-image:url(' | append: imageUrl | append: ');' -%}
{%- endif -%}

<article class="hit-card hit-card--featured">
  <div class="hit-card__inner hit-card__inner--featured" style="{{ bgStyle | escape }}">

    {%- if href and href != '' -%}
      <a class="hit-card__stretchedLink" href="{{ href | escape_once }}"{{ targetAttr }} aria-label="{{ title | escape }}"></a>
    {%- endif -%}

    <div class="hit-card__overlay"></div>

    <div class="hit-card__body hit-card__body--featured">

      {%- if typeLabel and typeLabel != '' -%}
        <div class="hit-card__badges">
          <span class="hit-card__badge">{{ typeLabel | escape }}</span>
        </div>
      {%- endif -%}

      <h3 class="hit-card__title hit-card__title--featured">{{ title | escape }}</h3>

      {%- if summary and summary != '' -%}
        <p class="hit-card__summary hit-card__summary--featured">{{ summary | escape }}</p>
      {%- endif -%}

      <div class="hit-card__cta">
        <a class="hit-button hit-button--secondary"
          href="{{ href | escape_once }}"
          {{ targetattr }}>
          {{ ctaText | escape }}
        </a>
      </div>

    </div>
  </div>
</article>"
}
